  1772	 * "命令都没应答"会掩盖后面所有现象。返回常量字符串，无副作用。
  1773	 */
  1774	static const char *sd1_sr_why(uint32_t sr)
  1775	{
  1776	  if ((sr & SD_SR_CMD_TIMEOUT) != 0)
  1777	    {
  1778	      return "cmd_to (command phase: no response)";
  1779	    }
  1780	
  1781	  if ((sr & SD_SR_CMD_RSP_CRC) != 0)
  1782	    {
  1783	      return "cmd_crc (response crc)";
  1784	    }
  1785	
  1786	  if ((sr & SD_SR_DATA_TIMEOUT) != 0)
  1787	    {
  1788	      return "data_to (data phase timeout)";
  1789	    }
  1790	
  1791	  if ((sr & SD_SR_DATA_CRC) != 0)
  1792	    {
  1793	      return "data_crc (data crc)";
  1794	    }
  1795	
  1796	  if ((sr & SD_SR_STARTBIT_ERROR) != 0)
  1797	    {
  1798	      return "startbit (no start bit on data/response)";
  1799	    }
  1800	
  1801	  if ((sr & SD_SR_FIFO_UNDERRUN) != 0)
  1802	    {
  1803	      return "fifo_ur";
  1804	    }
  1805	
  1806	  if ((sr & SD_SR_FIFO_OVERRUN) != 0)
  1807	    {
  1808	      return "fifo_or";
  1809	    }
  1810	
  1811	  if ((sr & SD_SR_CACHE_ERR) != 0)
  1812	    {
  1813	      return "cache_err";
  1814	    }
  1815	
  1816	  /* 失败却没有错误位置起：典型是命令压根没发出去，或纯等待超时。
  1817	   * 用 busy/done 区分"控制器卡在 busy"和"什么都没发生"。 */
  1818	  if ((sr & SD_SR_CMD_BUSY) != 0)
  1819	    {
  1820	      return "noerr_but_cmd_busy";
  1821	    }
  1822	
  1823	  if ((sr & SD_SR_CMD_DONE) != 0)
  1824	    {
  1825	      return "noerr_cmd_done";
  1826	    }
  1827	
  1828	  return "noerr_idle";
  1829	}
