  1831	/**
  1832	 * @brief 单次 I/O 调用的时间预算是否已经用光。
  1833	 *
  1834	 * @details 只在**重试之间**查，不会打断一次正常的传输。用光就按判死处理：
  1835	 *          这块（这一批）数据不要了，上层画空片/报错，重识别交给后台。
  1836	 *
  1837	 *          读写用不同预算：读是 UI 路径（瓦片/GPX），400 ms 就够；写本来就有
  1838	 *          合法的 2 s DAT0-program 等待（`SF32LB_SD_BUSY_US`），用 400 ms 会把
  1839	 *          健康卡误判死，所以写给 2.5 s —— 仍是有界，只是界更宽。
  1840	 */
  1841	static bool sd1_budget_spent(uint64_t t0, uint32_t budget_us)
  1842	{
  1843	  return (sd1_mono_us() - t0) > budget_us;
  1844	}
  1845	
  1846	#define SD1_READ_BUDGET_US   ((uint32_t)SF32LB_SD_CALL_BUDGET_US)
  1847	#define SD1_WRITE_BUDGET_US  ((uint32_t)SF32LB_SD_WRITE_BUDGET_US)
  1848	
  1849	static int sf32lb_sd_read_block_retry(uint64_t card_byte_addr,
  1850	                                      FAR uint8_t *dst)
  1851	{
  1852	  uint64_t t0 = sd1_mono_us();
  1853	  int ret;
  1854	  int t;
  1855	
  1856	  if (sd1_dead_fail_fast())
  1857	    {
  1858	      return -EIO;
  1859	    }
  1860	
  1861	  ret = sf32lb_sd_read_block(card_byte_addr, dst);
  1862	  if (ret >= 0)
  1863	    {
  1864	      sd1_restore_tran_clock();
  1865	      return ret;
  1866	    }
  1867	
  1868	  /* 先存下"第一次失败"的 SR：后面的 CMD12/解卡会覆盖 `g_sd_last_sr`，
  1869	   * 判死日志要报的是原始故障（Codex R3 P2-R1-10）。 */
  1870	  g_sd_call_first_sr = g_sd_last_sr;
  1871	
  1872	  /* Retry at the current clock first (official does not downclock on a
  1873	   * single glitch).  Drop to 6 MHz only after those retries fail, then
  1874	   * restore TRAN on success.
  1875	   */
  1876	
  1877	  for (t = 1; t <= SF32LB_SD_IO_RETRIES; t++)
  1878	    {
  1879	      if (sd1_budget_spent(t0, SD1_READ_BUDGET_US))
  1880	        {
  1881	          sd1_declare_dead("read budget");
  1882	          return -EIO;
  1883	        }
  1884	
  1885	      g_sd_diag.rd_retry++;
  1886	      sd1_recover_after_error();
  1887	
  1888	      /* 收尾本身也可能把预算吃光（Codex R3 P1-3）：重放前再查一次。 */
  1889	      if (sd1_budget_spent(t0, SD1_READ_BUDGET_US))
  1890	        {
  1891	          sd1_declare_dead("read budget after recover");
  1892	          return -EIO;
  1893	        }
  1894	
  1895	      ret = sf32lb_sd_read_block(card_byte_addr, dst);
  1896	      if (ret >= 0)
  1897	        {
  1898	          sd1_restore_tran_clock();
  1899	          syslog(LOG_WARNING, "SD: read addr=0x%llx recovered at %u kHz "
  1900	                 "(try %d)\n", (unsigned long long)card_byte_addr,
  1901	                 (unsigned)(g_sd_bus_hz / 1000), t);
  1902	          return ret;
  1903	        }
  1904	    }
  1905	
  1906	  if (sd1_budget_spent(t0, SD1_READ_BUDGET_US))
  1907	    {
  1908	      sd1_declare_dead("read budget");
  1909	      return -EIO;
  1910	    }
  1911	
  1912	  sd1_set_clock(SF32LB_SD_RETRY_CLOCK_HZ);
  1913	  g_sd_bus_hz = SF32LB_SD_RETRY_CLOCK_HZ;
  1914	  sd1_recover_after_error();
  1915	  ret = sf32lb_sd_read_block(card_byte_addr, dst);
  1916	  if (ret >= 0)
  1917	    {
  1918	      sd1_restore_tran_clock();
  1919	      syslog(LOG_WARNING,
  1920	             "SD: read addr=0x%llx recovered at 6 MHz then restored\n",
  1921	             (unsigned long long)card_byte_addr);
  1922	      return ret;
  1923	    }
  1924	
  1925	  g_sd_diag.rd_fail++;
  1926	  if (g_sd_fail_run < 0xffffu)
  1927	    {
  1928	      g_sd_fail_run++;
  1929	    }
  1930	  /* 把"连续第几次失败 / 当前总线时钟 / 累计重试"一起打出来，用来区分
  1931	   * 概率性抖动与永久性损坏：
  1932	   *   - run 每次失败都递增、成功即归零 ⇒ 抖动（单次故障）；
  1933	   *   - run 单调递增且 clk 一直停在 retry 档 ⇒ 永久性（卡已不应答）。
  1934	   * 现场只看单条 FAILED 日志分不出这两种，也看不出时钟是否已经掉档。 */
  1935	  syslog(LOG_ERR,
  1936	         "SD: read addr=0x%llx FAILED (tries=%d rca=0x%04x run=%u clk=%ukHz sr=0x%08lx why=%s rd_retry=%lu rd_fail=%lu)\n",
  1937	         (unsigned long long)card_byte_addr, SF32LB_SD_IO_RETRIES + 1,
  1938	         g_sd_rca, (unsigned)g_sd_fail_run, (unsigned)(g_sd_bus_hz / 1000),
  1939	         (unsigned long)g_sd_last_sr, sd1_sr_why(g_sd_last_sr),
  1940	         (unsigned long)g_sd_diag.rd_retry,
  1941	         (unsigned long)g_sd_diag.rd_fail);
  1942	  if (sd1_reinit_card(t0, SD1_READ_BUDGET_US) == 0)
  1943	    {
  1944	      ret = sf32lb_sd_read_block(card_byte_addr, dst);
  1945	      if (ret >= 0)
  1946	        {
  1947	          sd1_restore_tran_clock();
  1948	          syslog(LOG_WARNING,
  1949	                 "SD: read addr=0x%llx recovered after re-identify\n",
  1950	                 (unsigned long long)card_byte_addr);
  1951	        }
  1952	    }
  1953	
  1954	  return ret;
  1955	}
  1956	
  1957	static int sf32lb_sd_write_block_retry(uint64_t card_byte_addr,
  1958	                                       FAR const uint8_t *src)
  1959	{
  1960	  uint32_t crc0 = g_sd_diag.wr_crc;
  1961	  uint64_t t0 = sd1_mono_us();
  1962	  int ret;
  1963	  int t;
  1964	
  1965	  if (sd1_dead_fail_fast())
  1966	    {
  1967	      return -EIO;
  1968	    }
  1969	
  1970	  ret = sf32lb_sd_write_block(card_byte_addr, src);
  1971	  if (ret >= 0)
  1972	    {
  1973	      sd1_restore_tran_clock();
  1974	      return ret;
  1975	    }
  1976	
  1977	  g_sd_call_first_sr = g_sd_last_sr;
  1978	
  1979	  /* CRC: sampling glitch → drop the clock.  Timeout: DAT0-busy / aborted
  1980	   * program; downclocking does not help and the old "stay at 6 MHz" path
  1981	   * made sequential LittleFS flushes crawl.
  1982	   */
  1983	
  1984	  if (g_sd_diag.wr_crc > crc0)
  1985	    {
  1986	      sd1_set_clock(SF32LB_SD_RETRY_CLOCK_HZ);
  1987	      g_sd_bus_hz = SF32LB_SD_RETRY_CLOCK_HZ;
  1988	    }
  1989	
  1990	  for (t = 1; t <= SF32LB_SD_IO_RETRIES; t++)
  1991	    {
  1992	      if (sd1_budget_spent(t0, SD1_WRITE_BUDGET_US))
  1993	        {
  1994	          sd1_declare_dead("write budget");
  1995	          return -EIO;
  1996	        }
  1997	
  1998	      g_sd_diag.wr_retry++;
  1999	      sd1_recover_after_error();
  2000	
  2001	      if (sd1_budget_spent(t0, SD1_WRITE_BUDGET_US))
  2002	        {
  2003	          sd1_declare_dead("write budget after recover");
  2004	          return -EIO;
  2005	        }
  2006	
  2007	      ret = sf32lb_sd_write_block(card_byte_addr, src);
  2008	      if (ret >= 0)
  2009	        {
  2010	          break;
  2050	          if (ret >= 0)
  2051	            {
  2052	              sd1_restore_tran_clock();
  2053	              syslog(LOG_WARNING,
  2054	                     "SD: write addr=0x%llx recovered after re-identify\n",
  2055	                     (unsigned long long)card_byte_addr);
  2056	            }
  2057	        }
  2058	    }
  2059	
  2060	  return ret;
  2061	}
