  2063	/**
  2064	 * @brief CMD12 STOP_TRANSMISSION（R1b）。
  2065	 * @details CMD18/CMD25 之后必须发；CMD17/CMD24 超时若把卡留在 DATA 也要发。
  2066	 */
  2067	static int sf32lb_sd_cmd12(void)
  2068	{
  2069	  uint8_t r = sd1_send_cmd(12, 0);
  2070	
  2071	  (void)sd1_wait_card_idle();
  2072	  (void)sd1_wait_dat0(SF32LB_SD_WRITE_MAX_US);
