  2076	/* HAL_GetTick()/uwTick is not advanced under NuttX, so HAL_DMA_PollForTransfer
  2077	 * cannot time out.  Wait on the TC flag with our own clock, then let HAL
  2078	 * do channel-unlock cleanup (Timeout 0 is fine once TC is already set).
  2079	 */
  2080	
  2081	static uint8_t sf32lb_sd_dma_wait(FAR DMA_HandleTypeDef *hdma, bool is_write,
  2082	                                 uint64_t timeout_us)
  2083	{
  2084	  uint32_t tc;
  2085	  uint32_t te;
  2086	  uint32_t err_mask = SD_SR_DATA_TIMEOUT | SD_SR_DATA_CRC |
  2087	                      SD_SR_STARTBIT_ERROR |
  2088	                      (is_write ? SD_SR_FIFO_UNDERRUN : SD_SR_FIFO_OVERRUN);
  2089	  uint64_t deadline = sd1_mono_us() + timeout_us;
  2090	
  2091	  tc = DMA_FLAG_TC1 << (hdma->ChannelIndex & 0x1cU);
  2092	  te = DMA_FLAG_TE1 << (hdma->ChannelIndex & 0x1cU);
  2093	
  2094	  while ((hdma->DmaBaseAddress->ISR & tc) == 0)
  2095	    {
  2096	      if ((hdma->DmaBaseAddress->ISR & te) != 0)
  2097	        {
  2098	          (void)HAL_DMA_Abort(hdma);
  2099	          if (is_write)
  2100	            {
  2101	              g_sd_diag.wr_crc++;
  2102	            }
  2103	          else
  2104	            {
  2105	              g_sd_diag.rd_crc++;
  2106	            }
  2107	
  2108	          return SD_CRCERR;
  2109	        }
  2110	
  2111	      if ((hwp_sdmmc1->SR & err_mask) != 0)
  2112	        {
  2113	          (void)HAL_DMA_Abort(hdma);
  2114	          if ((hwp_sdmmc1->SR & SD_SR_DATA_TIMEOUT) != 0)
  2115	            {
  2116	              if (is_write)
  2117	                {
  2118	                  g_sd_diag.wr_timeout++;
  2119	                }
  2120	              else
  2121	                {
  2122	                  g_sd_diag.rd_timeout++;
  2123	                }
  2124	
  2125	              return SD_TIMEOUT;
  2126	            }
  2127	
  2128	          if (is_write)
  2129	            {
  2130	              g_sd_diag.wr_crc++;
  2131	            }
  2132	          else
  2133	            {
  2134	              g_sd_diag.rd_crc++;
  2135	            }
  2136	
  2137	          return SD_CRCERR;
  2138	        }
  2139	
  2140	      if (sd1_mono_us() >= deadline)
  2141	        {
  2142	          (void)HAL_DMA_Abort(hdma);
  2143	          if (is_write)
  2144	            {
  2145	              g_sd_diag.wr_timeout++;
  2146	            }
  2147	          else
  2148	            {
  2149	              g_sd_diag.rd_timeout++;
  2150	            }
  2151	
  2152	          return SD_TIMEOUT;
  2153	        }
  2154	    }
  2155	
  2156	  if (HAL_DMA_PollForTransfer(hdma, HAL_DMA_FULL_TRANSFER, 0) != HAL_OK)
  2157	    {
  2158	      (void)HAL_DMA_Abort(hdma);
  2159	      if (is_write)
  2160	        {
  2161	          g_sd_diag.wr_timeout++;
  2162	        }
  2163	      else
  2164	        {
  2165	          g_sd_diag.rd_timeout++;
  2166	        }
  2167	
  2168	      return SD_TIMEOUT;
  2169	    }
  2170	
  2171	  return SD_SUCCESS;
  2172	}
