  2174	/* Mirror of rthw_sdio_send_command() in drv_sdio.c for one data command:
  2175	 *   CLR_DATA_CTRL, SET_DATALEN(bytes), SET_DATA_CTRL,
  2176	 *   DATA_START only for reads before CMD; writes start DMA first, send CMD,
  2177	 *   DATA_START on CMD response (official CMDREND IRQ), then PollForTransfer,
  2178	 *   wait DATA_BUSY (TXACT) and DAT0.  CMD12 when nblocks > 1.
  2179	 *
  2180	 * cmd: 17/18 read, 24/25 write.  This MCU's SDMMC has no working PIO
  2181	 * multi-block path; DMA is mandatory in the SDK (#error without it).
  2182	 */
  2183	
  2184	static int sf32lb_sd_rt_xfer(bool is_write, uint64_t card_byte_addr,
  2185	                             FAR uint8_t *buf, uint32_t nblocks)
  2186	{
  2187	  FAR DMA_HandleTypeDef *hdma = &g_sd_dmah;
  2188	  uint32_t nbytes = nblocks * SD_HW_BLOCK_SIZE;
  2189	  uint32_t cmd_arg;
  2190	  uint32_t r1;
  2191	  uint32_t r2;
  2192	  uint32_t r3;
  2193	  uint32_t r4;
  2194	  uint32_t dcr;
  2195	  uint32_t dir;
  2196	  uint8_t cmd;
  2197	  uint8_t rsp_idx;
  2198	  uint8_t cmd_result;
  2199	  uint64_t dma_to;
  2200	#if SF32LB_SD_PROFILE
  2201	  uint64_t t0 = sf32lb_sd_now_us();
  2202	#endif
  2203	
  2204	  if (nblocks == 0 || nblocks > SF32LB_SD_CMD18_MAX_BLOCKS)
  2205	    {
  2206	      return -EINVAL;
  2207	    }
  2208	
  2209	  cmd = is_write ? (nblocks > 1 ? 25 : 24) : (nblocks > 1 ? 18 : 17);
  2210	  dir = is_write ? 0 : SD_DCR_R_WN;
  2211	  /* DMA 阶段也要截到剩余预算：数据错误/超时下这里原本能等 200 ms（读）或
  2212	   * 2 s（写），是"400 ms 预算"之外的又一个缺口（Codex R3 P1-3）。 */
  2213	  dma_to = is_write ? sd1_deadline_cap(SF32LB_SD_WRITE_WAIT_US)
  2214	                    : sd1_deadline_cap(200000ull);
  2215	
  2216	  hwp_sdmmc1->DCR = 0;
  2217	  (void)sd1_wait_card_idle();
  2218	  if (sd1_wait_dat0(SF32LB_SD_WRITE_MAX_US) != SD_SUCCESS)
  2219	    {
  2220	      return -EIO;
  2221	    }
  2222	
  2223	  if (is_write)
  2224	    {
  2225	      memcpy(g_sd_mblkbuf, buf, nbytes);
  2226	      up_clean_dcache((uintptr_t)g_sd_mblkbuf,
  2227	                      (uintptr_t)g_sd_mblkbuf + nbytes);
  2228	    }
  2229	  else
  2230	    {
  2231	      up_invalidate_dcache((uintptr_t)g_sd_mblkbuf,
  2232	                           (uintptr_t)g_sd_mblkbuf + nbytes);
  2233	    }
  2234	
  2235	  hwp_sdmmc1->DCR = 0;
  2236	  hwp_sdmmc1->SR = 0xffffffff;
  2237	  hwp_sdmmc1->DLR = nbytes - 1;
  2238	  dcr = ((SD_HW_BLOCK_SIZE - 1) << SD_DCR_BLOCK_SIZE_Pos);
  2239	  dcr |= (SF32LB_SD_WIRE_MODE << SD_DCR_WIRE_MODE_Pos) | dir;
  2240	  dcr |= SD_DCR_TRAN_DATA_EN;
  2241	  hwp_sdmmc1->DCR = dcr;
  2242	  if (!is_write)
  2243	    {
  2244	      hwp_sdmmc1->DCR |= SD_DCR_DATA_START;
  2245	    }
  2246	
  2247	  if (sf32lb_sd_dma_prepare(is_write) != OK)
  2248	    {
  2249	      goto stop;
  2250	    }
  2251	
  2252	  if (is_write)
  2253	    {
  2254	      if (HAL_DMA_Start(hdma, (uint32_t)g_sd_mblkbuf,
  2255	                        (uint32_t)&hwp_sdmmc1->FIFO, nbytes / 4) != HAL_OK)
  2256	        {
  2257	          goto stop;
  2258	        }
  2259	    }
  2260	  else if (HAL_DMA_Start(hdma, (uint32_t)&hwp_sdmmc1->FIFO,
  2261	                         (uint32_t)g_sd_mblkbuf, nbytes / 4) != HAL_OK)
  2262	    {
  2263	      goto stop;
  2264	    }
  2265	
  2266	  cmd_arg = sf32lb_sd_cmd_arg(card_byte_addr);
  2267	  cmd_result = sd1_send_cmd(cmd, cmd_arg);
  2268	  if (cmd_result != SD_SUCCESS)
  2269	    {
  2270	      (void)HAL_DMA_Abort(hdma);
  2271	      goto stop;
  2272	    }
  2273	
  2274	  sd1_get_rsp(&rsp_idx, &r1, &r2, &r3, &r4);
  2275	  if (rsp_idx != cmd)
  2276	    {
  2277	      (void)HAL_DMA_Abort(hdma);
  2278	      goto stop;
  2279	    }
  2280	
  2281	  if (is_write)
  2282	    {
  2283	      if ((r1 & SF32LB_SD_R1_STATE_MASK) == SF32LB_SD_R1_STATE_PRG)
  2284	        {
  2285	          (void)HAL_DMA_Abort(hdma);
  2286	          g_sd_last_sr = r1;
  2287	          (void)sd1_wait_dat0(SF32LB_SD_WRITE_MAX_US);
  2288	          goto stop;
  2289	        }
  2290	
  2291	      /* Official drv_sdio.c: DATA_START in the CMDREND IRQ, after the
  2292	       * card accepted CMD24/CMD25.  Starting the data phase before the
  2293	       * response left the card in the data state. */
  2294	      hwp_sdmmc1->IER = SD_IER_DATA_DONE_MASK;
  2295	      hwp_sdmmc1->DCR |= SD_DCR_DATA_START;
  2296	    }
  2297	
  2298	  cmd_result = sf32lb_sd_dma_wait(hdma, is_write, dma_to);
  2299	  if (cmd_result != SD_SUCCESS)
  2300	    {
  2301	      goto stop;
  2302	    }
  2303	
  2304	  if (is_write)
  2305	    {
  2306	      cmd_result = sd1_wait_write();
  2307	      if (cmd_result != SD_SUCCESS)
  2308	        {
  2309	          goto stop;
  2310	        }
  2311	    }
  2312	
  2313	  (void)sd1_wait_card_idle();
  2314	  if (nblocks > 1)
  2315	    {
  2316	      if (sf32lb_sd_cmd12() < 0)
  2317	        {
  2318	          sd1_recover_after_error();
  2319	          return -EIO;
  2320	        }
  2321	
  2322	      (void)sd1_wait_card_idle();
  2323	      if (is_write &&
