  3322	/**
  3323	 * @brief 把坏掉的 LFS 挂载点重新挂上（哪个坏挂哪个）。
  3324	 *
  3325	 * @details 只在"**卡还能读**但 LFS 用不了"时才动手 —— 门就是用 FAT 探的，
  3326	 *          理由同上：FAT 与 LFS 同卡，FAT 能读说明卡没坏，那问题就在 LFS
  3327	 *          实例上（硬复位救回卡之后 LittleFS 的 RAM 内状态不会自愈，必须重挂）。
  3328	 *          卡读不到时直接返回，把舞台留给 SD 层的判死/硬复位。
  3329	 *
  3330	 *          两个坑，都踩过：
  3331	 *          1. /mnt/kv **不能**直接重调 sf32lb_sd_mount_kv()——它开头
  3332	 *             `if (g_sd_kv_mtd != NULL) return OK;` 会立刻返回成功却根本不重挂。
  3333	 *             所以这里走 umount + 按设备名 mount，不重复注册 MTD。
  3334	 *          2. kv 的开机挂载带 "autoformat"；恢复路径上**刻意不传**，而且
  3335	 *             按"LFS 永不格式化"的要求，开机那条也要去掉（见 mount_kv）。
  3336	 *
  3337	 *          不要在持有 SD 总线锁的路径里调用：mount 内部还要走 SD I/O，
  3338	 *          g_sd_lock 不可重入，会自锁。只从 diag 线程调。
  3339	 *
  3340	 * @return 0 全部可用（含本次修好的）；-EAGAIN 卡读不到；负 errno 为失败。
  3341	 */
  3342	int sf32lb_sd_fs_heal(void)
  3343	{
  3344	  struct statfs st;
  3345	  int ret = 0;
  3346	  int one;
  3347	
  3348	  /* 判死期间**不要**重挂：mount 里会调 `sf32lb_sd_identify()`（不持总线锁），
  3349	   * 与后台复活任务的硬复位/identify 交错会同时改控制器和时钟（Codex R1 P1-1）。
  3350	   * 这里的 `-EAGAIN` 就是"卡读不到"的既有语义，diag 会按 cooldown 再看。 */
  3351	  if (sf32lb_sd_dead())
  3352	    {
  3353	      syslog(LOG_WARNING,
  3354	             "LFS: heal skipped, SD declared dead (background revive owns it)\n");
  3355	      return -EAGAIN;
  3356	    }
  3357	
  3358	  if (statfs(SF32LB_SD_FAT_MOUNTPOINT, &st) != 0)
  3359	    {
  3360	      syslog(LOG_WARNING, "LFS: heal skipped, card not readable via %s (SD layer owns it)\n",
  3361	             SF32LB_SD_FAT_MOUNTPOINT);
  3362	      return -EAGAIN;
  3363	    }
  3364	
  3365	  if (statfs(SF32LB_SD_MOUNTPOINT, &st) != 0)
  3366	    {
  3367	      /* statfs 自己就是一次块 I/O：它可能**刚刚**把卡判死（预算耗尽/解卡失败）。
  3368	       * 这里必须复查，否则会带着判死状态去 umount + mount，而 mount 里的
  3369	       * identify 不持总线锁，会和复活任务撞在一起（Codex R2 P1-1）。 */
  3370	      if (sf32lb_sd_dead())
  3371	        {
  3372	          syslog(LOG_WARNING, "LFS: heal abort, SD became dead during probe\n");
  3373	          return -EAGAIN;
  3374	        }
  3375	
  3376	      syslog(LOG_WARNING, "LFS: remount %s (card readable, FS is not)\n",
  3377	             SF32LB_SD_MOUNTPOINT);
  3378	      (void)umount(SF32LB_SD_MOUNTPOINT);
  3379	      one = sf32lb_sd_mount_littlefs(0);
  3380	      syslog(one == 0 ? LOG_WARNING : LOG_ERR,
  3381	             "LFS: remount %s ret=%d\n", SF32LB_SD_MOUNTPOINT, one);
  3382	      if (one != 0)
  3383	        {
  3384	          ret = one;
  3385	        }
  3386	    }
  3387	
  3388	  if (statfs(SF32LB_SD_KV_MOUNTPOINT, &st) != 0)
  3389	    {
  3390	      /* 与 /mnt/lfs 同理：这次 statfs 可能刚把卡判死，不能再带着判死去重挂
  3391	       *（Codex R3 P1-1）。 */
  3392	      if (sf32lb_sd_dead())
  3393	        {
  3394	          syslog(LOG_WARNING, "LFS: heal abort, SD became dead during kv probe\n");
  3395	          return -EAGAIN;
  3396	        }
  3397	
  3398	      syslog(LOG_WARNING, "LFS: remount %s (card readable, FS is not)\n",
  3399	             SF32LB_SD_KV_MOUNTPOINT);
  3400	      (void)umount(SF32LB_SD_KV_MOUNTPOINT);
  3401	      one = mount(SF32LB_SD_KV_DEV, SF32LB_SD_KV_MOUNTPOINT, "littlefs",
  3402	                  0, NULL);
  3403	      syslog(one == 0 ? LOG_WARNING : LOG_ERR,
  3404	             "LFS: remount %s ret=%d errno=%d\n",
  3405	             SF32LB_SD_KV_MOUNTPOINT, one, errno);
  3406	      if (one != 0 && ret == 0)
  3407	        {
  3408	          ret = -errno;
  3409	        }
  3410	    }
  3411	
  3412	  return ret;
  3413	}
