  3727	/* Halve the card clock twice and re-measure. If the per-sector cost tracks the
  3728	 * clock we are bus-limited (the divider or its source clock is wrong); if it
  3729	 * barely moves, the cost is fixed per-CMD17 latency and only multi-block
  3730	 * transfers can help.
  3731	 */
  3732	
  3733	static void sf32lb_sd_bench_clocks(FAR struct mtd_dev_s *mtd,
  3734	                                   FAR uint8_t *buf)
  3735	{
  3736	  static const uint32_t hz[] =
  3737	  {
  3738	    SF32LB_SD_TRAN_CLOCK_HZ,
  3739	    SF32LB_SD_TRAN_CLOCK_HZ / 2,
  3740	    SF32LB_SD_TRAN_CLOCK_HZ / 4
  3741	  };
  3742	
  3743	  uint32_t hclk = HAL_RCC_GetHCLKFreq(CORE_ID_HCPU);
  3744	  unsigned int i;
  3745	
  3746	  for (i = 0; i < sizeof(hz) / sizeof(hz[0]); i++)
  3747	    {
  3748	      uint64_t t0;
  3749	      uint64_t dt;
  3750	      ssize_t ret = 0;
  3751	      uint32_t div;
  3752	      int j;
  3753	
  3754	      nxmutex_lock(&g_sd_lock);
  3755	      sd1_set_clock(hz[i]);
  3756	      div = ((hwp_sdmmc1->CLKCR & SD_CLKCR_DIV_Msk) >>
  3757	             SD_CLKCR_DIV_Pos) + 1;
  3758	      nxmutex_unlock(&g_sd_lock);
  3759	
  3760	      t0 = sf32lb_sd_now_us();
  3761	      for (j = 0; j < 32 && ret >= 0; j++)
  3762	        {
  3763	          ret = MTD_BREAD(mtd, j, 1, buf);
  3764	        }
  3765	
  3766	      dt = sf32lb_sd_now_us() - t0;
  3767	      syslog(LOG_INFO,
  3768	             "SDPROF: clk  div=%-3lu (~%lu kHz) %lu us/sector%s\n",
  3769	             (unsigned long)div,
  3770	             (unsigned long)(hclk / div / 1000),
  3771	             (unsigned long)(dt / 32),
  3772	             ret < 0 ? " READ FAILED" : "");
  3773	    }
  3774	
  3775	  nxmutex_lock(&g_sd_lock);
  3776	  sd1_set_clock(g_sd_bus_hz);
  3777	  nxmutex_unlock(&g_sd_lock);
  3778	}
