  5202	static void map_page_fit_pts(map_page_t * page, const vmap_route_pt_t * pts,
  5203	    uint32_t n)
  5204	{
  5205	    double min_lon;
  5206	    double max_lon;
  5207	    double min_lat;
  5208	    double max_lat;
  5209	    double cx;
  5210	    double cy;
  5211	    uint32_t i;
  5212	    int z;
  5213	    int32_t w = 0;
  5214	    int32_t h = 0;
  5215	    const int32_t pad = 20;
  5216	
  5217	    if (!page || !page->map || !pts || n < 2u) {
  5218	        return;
  5219	    }
  5220	
  5221	    min_lon = max_lon = pts[0].lon;
  5222	    min_lat = max_lat = pts[0].lat;
  5223	    for (i = 1u; i < n; i++) {
  5224	        if (pts[i].lon < min_lon) {
  5225	            min_lon = pts[i].lon;
  5226	        }
  5227	        if (pts[i].lon > max_lon) {
  5228	            max_lon = pts[i].lon;
  5229	        }
  5230	        if (pts[i].lat < min_lat) {
  5231	            min_lat = pts[i].lat;
  5232	        }
  5233	        if (pts[i].lat > max_lat) {
  5234	            max_lat = pts[i].lat;
  5235	        }
  5236	    }
  5237	
  5238	    cx = (min_lon + max_lon) * 0.5;
  5239	    cy = (min_lat + max_lat) * 0.5;
  5240	    vmap_view_get_buffer_size(page->map, &w, &h);
  5241	
  5242	    for (z = VMAP_ZOOM_MAX; z >= VMAP_ZOOM_MIN; z--) {
  5243	        int32_t x0;
  5244	        int32_t y0;
  5245	        int32_t x1;
  5246	        int32_t y1;
  5247	
  5248	        vmap_view_set_view(page->map, cx, cy, z);
  5249	        (void)vmap_view_geo_to_viewport_raw(page->map, min_lon, min_lat, &x0, &y0);
  5250	        (void)vmap_view_geo_to_viewport_raw(page->map, max_lon, max_lat, &x1, &y1);
  5251	        if (x0 > x1) {
  5252	            int32_t t = x0;
  5253	
  5254	            x0 = x1;
  5255	            x1 = t;
  5256	        }
  5257	        if (y0 > y1) {
  5258	            int32_t t = y0;
  5259	
  5260	            y0 = y1;
  5261	            y1 = t;
  5262	        }
  5263	        if (x0 >= pad && y0 >= pad && x1 < w - pad && y1 < h - pad) {
  5264	            return;
  5265	        }
  5266	    }
  5267	}
